INSERT INTO engine_bug_queue (bug_class, title, severity, owner_cluster, root_cause, prevention_rule, probe_type, probe_logic, status, concepts_affected, fixed_in_files, discovered_in_session, row_type) VALUES
('field3d_kt_x_readout_spec_not_implemented', 'kt_x_readout spec''d in the concept JSON (engine_build_spec + STATE_1 visible_elements + glow_focal) but never built as a DOM element — STATE_1 renders zero numeric readout for its whole 5s reveal + hold', 'CRITICAL', 'peter_parker:renderer_primitives', 'buildKinematics1dTrack() only created three DOM readouts (kt_d_readout, kt_dx_readout, kt_lap_counter). kt_x_readout — the plain position HUD json_author added to fix an earlier "STATE_1 pre-spoils Δx" bug — had no matching document.createElement anywhere, so it silently rendered nothing: STATE_1''s visible_elements list and glow_focal both referenced a DOM id that never existed. Underneath, the STATE_1 position_intro digit-roll logic was still writing into kt_dx_readout labelled "Δx =", so the original pre-spoil bug was still live, just invisible (STATE_1''s hidden kt_dx_readout silently held the STATE_1 value with no on-screen effect). Confirmed independently by quality_auditor''s Playwright probe and eye-walker''s STATE_1__frozen.png (track/ticks/flag/runner visible, zero readout).', 'Every id referenced in a state''s visible_elements or a phase''s glow_focal MUST resolve to either a real 3D mesh (ktFindById) or a real DOM element (document.getElementById) — grep the renderer for a matching createElement/addToScene call before declaring a new engine_build_spec object implemented. A glow_focal pointing at a nonexistent DOM id is a silent Rule-29/32e violation: the glow call still runs, dims every peer, and lights nothing.', 'js_eval', 'For any field_3d concept with scenario_type kinematics_1d_track: (1) static — every DOM-overlay id appearing in any state''s visible_elements array (kt_x_readout/kt_d_readout/kt_dx_readout/kt_lap_counter) has a matching `id = "<id>"` assignment inside buildKinematics1dTrack() in field_3d_renderer.ts; (2) runtime — SET_STATE to STATE_1, wait for settle, assert document.getElementById("kt_x_readout").style.display === "block" and .textContent matches /^x = [+-]\d+\.\d m$/, and that it carries the glow-pulse class during the phases[] window whose glow_focal === "kt_x_readout".', 'FIXED', ARRAY['displacement_vs_distance'], ARRAY['src/lib/renderers/field_3d_renderer.ts'], 'session_2026-07-25_displacement_vs_distance_fix2', 'incident'),
('field3d_kt_dual_formula_overlay_not_suppressed', 'kinematics_1d_track built its own dedicated Cambria-Math #kt_formula panel but the generic #formula_overlay suppression allowlist (magnetisation/motional_emf_rod/ac_generator) omitted the new scenario_type, so both render the SAME formula string simultaneously', 'MAJOR', 'peter_parker:renderer_primitives', 'applyState()''s generic formula-overlay block (~L30977) only hides #formula_overlay for an enumerated scenario_type allowlist. kinematics_1d_track was never added despite shipping its own #kt_formula surface in the same build, so every state with a non-null track formula_overlay showed the 19px Cambria-Math serif panel bottom-center (dedicated) AND the 13px monospace #formula_overlay bottom-right (generic, duplicate string) at once — also the direct cause of a Gate 9 layout collision on STATE_5 (kt_sliders x formula_overlay).', 'Any NEW field_3d scenario_type that builds its own dedicated formula/equation panel MUST be added to the #formula_overlay suppression allowlist in the SAME change (grep field_3d_renderer.ts for "own dedicated formula panel" to find the list) — otherwise the generic panel silently duplicates it and can layout-collide with the scenario''s own sliders.', 'js_eval', 'For every field_3d scenario_type that builds a dedicated formula DOM id (grep for "own dedicated formula panel" comments to enumerate: #mag_formula/#mem_formula/#acg_formula/#kt_formula/…): on any state with a non-null formula string, assert getComputedStyle(#formula_overlay).display === "none" (exactly one visible formula surface at a time).', 'FIXED', ARRAY['displacement_vs_distance'], ARRAY['src/lib/renderers/field_3d_renderer.ts'], 'session_2026-07-25_displacement_vs_distance_fix2', 'incident'),
('field3d_kt_distance_accumulator_seek_order_dependent', 'window.PM_ktD (path-length odometer) was a mutable frame-to-frame accumulator that only integrates correctly under monotonically-increasing time — THE EYE''s dense+frozen capture pins one long-lived session per state and is NOT guaranteed monotonic, so a backward SET_TIME_FREEZE jump gets summed as if it were real motion, permanently inflating d for the rest of that state''s captures (STATE_2 read d=200 vs true ~40, STATE_3 climbed to d=240 vs true cap 80, ghost arrow ran off-canvas)', 'CRITICAL', 'peter_parker:renderer_primitives', 'animate()''s SET_TIME_FREEZE handling advances `time` forward by dtStep toward freezeAtTime every frame, but if a NEW target is BEHIND the clock''s current position (freezeAtTime < time), the very next frame''s `time + dtStep >= freezeAtTime` check is already true, so time SNAPS backward in one frame with no intermediate frames visited. updateKinematics1dTrackFrame''s accumulator (`PM_ktD += |x(t)-x(t-1)|`) cannot distinguish a real motion step from a capture-harness time-jump, so it adds the full backward displacement as fictitious distance. Verified live (Playwright, clean sequential SET_STATE, single settle) reads CORRECT — this is a genuine capture-harness-interaction bug, not a live-playback bug, but THE EYE is a mandatory permanent gate (CLAUDE.md §5) so it still had to be fixed in the renderer. A secondary latent bug in the SAME code path was exposed once the primary fix landed: kt_ghost_arrow/kt_ghost_strike used one-sided `if (tMs >= X) obj.visible = true` toggles with no `else obj.visible = false`, so a backward seek within a state left them visibly stuck ON from a later capture even after PM_ktD itself was fixed.', 'Any live-instrument accumulator field_3d authors as "d += |Δx| each frame" (per-frame path integral) is ONLY valid if the renderer never receives non-monotonic time targets for that state — which THE EYE''s dense/frozen capture does not guarantee. Wherever the authored motion for a state is a reproducible piecewise schedule (not free human input), compute the accumulated quantity as a CLOSED-FORM function of state-local ms instead (sum |Δx| across the schedule''s known breakpoints, using the exact position function at each breakpoint plus a partial term for the in-progress segment) — a pure function of tMs is immune to seek/jump/re-entry order by construction (Rule 26). Reserve a genuine per-frame accumulator ONLY for states driven by live untestable human input (e.g. a sandbox/explore state''s persistent session odometer). Separately: EVERY `if (tMs >= X) obj.visible = true` reveal toggle in a per-frame update function must have a matching `else obj.visible = false` (and reset any dependent length/opacity) — a one-sided toggle leaks stale visibility across non-monotonic seeks even after the underlying value becomes seek-order-safe.', 'js_eval', 'For any field_3d scenario built as a reproducible piecewise schedule (kinematics_1d_track and any future scenario_type sharing the pattern): via Playwright, SET_STATE into a guided state, drive it to a LATE at_ms via SET_TIME_FREEZE, THEN drive it to an EARLY at_ms via a second SET_TIME_FREEZE (simulating THE EYE''s non-monotonic dense-then-frozen or out-of-order dense capture) — assert the accumulator field (e.g. window.PM_ktD) after the backward seek equals the value a fresh SET_STATE + single forward seek to that same early at_ms would produce (i.e. it must not retain any contribution from the discarded later time). Also assert any one-shot reveal mesh gated on the same tMs (kt_ghost_arrow/kt_ghost_strike) is NOT visible when tMs is before its reveal threshold, regardless of capture order.', 'FIXED', ARRAY['displacement_vs_distance'], ARRAY['src/lib/renderers/field_3d_renderer.ts'], 'session_2026-07-25_displacement_vs_distance_fix2', 'incident')
